     command, core_data, write_en, write_data, data_address,
     flash_write_done, flash_write_en);
  input clk, rst_n, rx, flash_write_done;
  input [31:0] core_data;
  output tx, core_halt, write_en, flash_write_en;
  output [7:0] command;
  output [31:0] write_data, data_address;
  wire clk, rst_n, rx, flash_write_done;
  wire [31:0] core_data;
  wire tx, core_halt, write_en, flash_write_en;
  wire [7:0] command;
  wire [31:0] write_data, data_address;
  debug_controller_v2_debug_if_debug_interface_v2_default
       dut(.debug_if_clk (clk), .debug_if_rst_n (rst_n), .debug_if_tx
       (tx), .debug_if_rx (rx), .debug_if_core_halt (core_halt),
       .debug_if_command (command), .debug_if_core_data (core_data),
       .debug_if_write_en (write_en), .debug_if_write_data
       (write_data), .debug_if_data_address (data_address),
       .debug_if_flash_write_done (flash_write_done),
       .debug_if_flash_write_en (flash_write_en));
endmodule

